using DeskTip.Core;
using System.Text.Json;

int passed = 0;
void Check(string name, bool value) { if (!value) throw new Exception("FAIL " + name); Console.WriteLine("PASS " + name); passed++; }
void Reject(string name, Action action) { try { action(); } catch (Exception e) when (e is ArgumentException or JsonException) { Check(name, true); return; } Check(name, false); }
DateTime D(string time) => DateTime.Parse("2026-10-14 " + time);
AppSettings Default() => new() { Calendar = JsonSerializer.Deserialize<CalendarData>(File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "calendar-2026.json")))! };
var settings = Default(); var rule = settings.Reminders[0]; settings.Validate(); var calendar = settings.Calendar;
