Check("templates are independent copies", first.Id != second.Id && second.Periods[0].Start == "10:00");
Check("default is hydration only", settings.Reminders.Count == 1 && rule.TemplateKey == "water");
var expected = new[] { "10:50", "11:40", "14:40", "15:30", "16:20", "17:10", "18:00" };
Check("original work grid preserved", ScheduleEngine.Slots(rule, calendar, D("00:00")).Select(t => t.ToString("HH:mm")).SequenceEqual(expected));
Check("lunch quiet", ScheduleEngine.ActivePeriod(rule, calendar, D("12:00")) == null);
Check("end exclusive", ScheduleEngine.ActivePeriod(rule, calendar, D("11:45")) == null && ScheduleEngine.ActivePeriod(rule, calendar, D("18:30")) == null);
Check("next skips lunch", ScheduleEngine.Next(rule, calendar, D("11:40")) == D("14:40"));
