Check("restart uses period grid", ScheduleEngine.Next(rule, calendar, D("10:35")) == D("10:50"));
Check("national holiday", !calendar.IsWorkday(DateTime.Parse("2026-10-01")));
Check("Saturday makeup", calendar.IsWorkday(DateTime.Parse("2026-10-10")));
Check("Sunday makeup", calendar.IsWorkday(DateTime.Parse("2026-09-20")));
Check("normal weekend", !calendar.IsWorkday(DateTime.Parse("2026-10-17")));
Check("holiday no interval slots", !ScheduleEngine.Slots(rule, calendar, DateTime.Parse("2026-10-01")).Any());
Check("unknown year weekday fallback", calendar.IsWorkday(DateTime.Parse("2027-01-04")));
Check("weekend next workday", ScheduleEngine.Next(rule, calendar, DateTime.Parse("2026-10-16 18:30")) == DateTime.Parse("2026-10-19 10:50"));
var read = TemplateCatalog.Create("read");
Check("daily reminder on weekend", ScheduleEngine.Next(read, calendar, DateTime.Parse("2026-10-17 10:00")) == DateTime.Parse("2026-10-17 21:00"));
Check("daily reminder during national holiday", ScheduleEngine.Next(read, calendar, DateTime.Parse("2026-10-01 10:00")) == DateTime.Parse("2026-10-01 21:00"));
var backup = TemplateCatalog.Create("backup");
Check("custom Friday schedule", ScheduleEngine.Next(backup, calendar, D("18:00")) == DateTime.Parse("2026-10-16 17:45"));
