read.Times = new() { "21:00", "08:00", "13:30" };
Check("fixed times sorted", ScheduleEngine.Slots(read, calendar, D("00:00")).Select(d => d.ToString("HH:mm")).SequenceEqual(new[] { "08:00", "13:30", "21:00" }));
